import warnings
warnings.filterwarnings('ignore')
t=df['t'].values;A=df['A'].values;y=df['dA_dt'].values
v=np.var(y)
best=(9,)
for p2 in [6,8,9,10,11,12,14]:
    base=np.c_[np.sqrt(t), np.log(1+p2*A)*t, np.log(1+A)**2]
    for p in np.arange(-3,3.01,0.25):
        for q in np.arange(-1,3.01,0.25):
            for k in np.arange(0,3.01,0.25):
                h=t**p*A**q*np.exp(-k*A)
                M=np.c_[base,h]
                c=np.linalg.lstsq(M,y,rcond=None)[0]
                e=np.mean((M@c-y)**2)/v
                if e<best[0]: best=(e,p2,p,q,k,np.round(c,4))
